\begin{tikzpicture}
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{rationalFill}{HTML}{D4E8FF}
\definecolor{integerFill}{HTML}{FCE8D5}
\definecolor{naturalFill}{HTML}{DCEBE0}
\definecolor{irrationalFill}{HTML}{FCDFE1}
\draw[black,line width=0.8pt,rounded corners=4mm] (0,0) rectangle (16,-13);
\node[font=\bfseries] at (8,-0.55) {Real Numbers};
\node at (8,-1.35) {All numbers we have been working with so far are collectively called real numbers.};
\draw[black,line width=0.8pt,fill=rationalFill,rounded corners=1mm] (0.4,-2.1) rectangle (15.6,-8.3);
\node[anchor=west,font=\bfseries] at (0.7,-2.6) {Rational Numbers};
\node[anchor=north west,align=left,text width=6.2cm] at (0.7,-3.1) {A number that can be written as $\frac{a}{b}$ where $a$ and $b$ are integers.};
\node at (1.3,-5.3) {$-\frac{12}{5}$};
\node at (2.7,-5.3) {$68\%$};
\node at (4.0,-5.3) {$0.42$};
\node at (5.3,-5.3) {$\frac{8}{3}$};
\node at (6.4,-5.3) {$0.\dot{3}$};
\node at (7.5,-5.3) {$4\frac{2}{5}$};
\draw[black,line width=0.8pt,fill=integerFill,rounded corners=1mm] (8.5,-2.5) rectangle (15.4,-7.9);
\node[anchor=west,font=\bfseries] at (8.8,-2.95) {Integers};
\node[anchor=north west,align=left,text width=3.2cm] at (8.8,-3.4) {Whole numbers, including negative numbers.};
\node at (9.2,-7.0) {$-2$};
\node at (10.5,-7.0) {$\sqrt{9}$};
\node at (11.9,-7.0) {$\frac{18}{3}$};
\node at (13.1,-7.0) {$8$};
\node at (14.4,-7.0) {$-183$};
\draw[black,line width=0.8pt,fill=naturalFill,rounded corners=1mm] (12.2,-2.8) rectangle (15.3,-6.0);
\node[font=\bfseries] at (13.75,-3.25) {Natural Numbers};
\node[align=center,text width=2.8cm] at (13.75,-4.15) {Positive whole numbers};
\node at (12.55,-5.25) {$1$};
\node at (13.1,-5.25) {$2$};
\node at (13.65,-5.25) {$3$};
\node at (14.2,-5.25) {$62$};
\node at (14.85,-5.25) {$2719$};
\draw[black,line width=0.8pt,fill=irrationalFill,rounded corners=1mm] (0.4,-8.9) rectangle (15.6,-12.6);
\node[font=\bfseries] at (8,-9.35) {Irrational Numbers};
\node[align=center] at (8,-10.45) {Irrational numbers cannot be written as $\frac{a}{b}$ where $a$ and $b$ are integers.\\As decimals, they are non-terminating and non-recurring.\\They go on forever with no repeating pattern.};
\node at (2.6,-11.95) {$\pi\approx3.141592\ldots$};
\node at (6.0,-11.95) {$\sqrt{2}\approx1.4142135\ldots$};
\node at (9.7,-11.95) {$\sqrt{3}\approx1.7320508\ldots$};
\node at (13.4,-11.95) {$e\approx2.718281\ldots$};
\end{tikzpicture}

